-- Schema only. Performance indexes and partitions intentionally live in database-labs.
CREATE TABLE inventory_balance (id BIGSERIAL PRIMARY KEY, sku_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, on_hand BIGINT NOT NULL, reserved BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 0, UNIQUE(sku_id, warehouse_id));
CREATE TABLE inventory_reservation (id BIGSERIAL PRIMARY KEY, reservation_key VARCHAR(128) NOT NULL UNIQUE, order_id VARCHAR(64) NULL, sku_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, quantity BIGINT NOT NULL, status VARCHAR(32) NOT NULL, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE inventory_ledger (id BIGSERIAL PRIMARY KEY, sku_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, delta BIGINT NOT NULL, reason VARCHAR(64) NOT NULL, reference_key VARCHAR(128) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE inbox_event (id BIGSERIAL PRIMARY KEY, consumer_name VARCHAR(128) NOT NULL, event_id VARCHAR(36) NOT NULL, processed_at TIMESTAMP NOT NULL, UNIQUE(consumer_name,event_id));
CREATE TABLE outbox_event (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(36) NOT NULL UNIQUE, aggregate_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, payload_json JSONB NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL, processed_at TIMESTAMP NULL);
CREATE TABLE job_run (id BIGSERIAL PRIMARY KEY, job_name VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, last_cursor VARCHAR(255) NULL, processed_count BIGINT NOT NULL DEFAULT 0, failed_count BIGINT NOT NULL DEFAULT 0, started_at TIMESTAMP NOT NULL, finished_at TIMESTAMP NULL, trace_id VARCHAR(64) NULL);
